/// <summary>
/// Service class for auto-settling customer transactions grouped by invoice.
/// </summary>
class METAutoSettleCustomerTransactionsService
{
}

Method.Source:
/// <summary>
/// Entry point for processing settlement logic.
/// </summary>
/// <param name="_contract">Contract containing the query to execute.</param>
public void process(METAutoSettleCustomerTransactionsContract _contract)
{        
    // Initialize query runner from the packed query in the contract
    QueryRun queryRun = new QueryRun(_contract.getQuery());        

    // Iterate through each invoice record returned by the query
    while (queryRun.next())
    {
        try
        {                
            ttsbegin;

            // Retrieve CustTrans and CustTransOpen invoice records from the query
            CustTrans custTrans = queryRun.get(tableNum(CustTrans));
            CustTransOpen custTransOpen = queryRun.get(tableNum(CustTransOpen));

            setPrefix(strFmt("@MET:AutoSettlementPrefix", custTrans.AccountNum, custTrans.Invoice));

            this.processOpenInvoice(custTrans, custTransOpen);

            ttscommit;
        }
        catch (Exception::CLRError)
        {
            // Log CLR exceptions
            System.Exception clrEx = CLRInterop::getLastException();
            error(strFmt("@MET:CLRAutoSettlement", clrEx.get_Message()));
        }
        catch (Exception::Error)
        {
            // Log X++ exceptions
            error("@MET:XPPAutoSettlement");
        }
    }       
}

/// <summary>
/// Bug 383147: E2E EOD Payment Summary file_CCC-0048 to auto settle invoices against payments
/// Processes open invoices for settlement.
/// </summary>
/// <param name = "_custTrans">Customer transaction record.</param>
/// <param name = "_custTransOpen">Open customer transaction record.</param>
void processOpenInvoice(CustTrans _custTrans, CustTransOpen _custTransOpen)
{
    // Retrieve the corresponding open payment for that invoice
    CustTrans custTransPayment;
    CustTransOpen custTransOpenPayment;

    select firstonly custTransOpenPayment
         exists join custTransPayment
               where custTransPayment.AccountNum == _custTrans.AccountNum
                  && custTransPayment.Invoice == _custTrans.Invoice
                  && custTransPayment.TransType == LedgerTransType::GeneralJournal
                  && custTransOpenPayment.AccountNum == custTransPayment.AccountNum
                  && custTransOpenPayment.RefRecId == custTransPayment.RecId;

    // if payment is found
    if (custTransOpenPayment)
    {            
        // mark both transactions
        Common originator = CustTable::find(_custTrans.AccountNum);
        CustVendOpenTransManager manager = CustVendOpenTransManager::construct(originator);
        manager.updateTransMarked(_custTransOpen, NoYes::Yes); // invoice
        manager.updateTransMarked(custTransOpenPayment, NoYes::Yes); // payment

        // settle the invoice with the payment
        if (manager.validateMarkedTotalWithinOverUnder() && manager.validateMarkedWithCrossRate()) // CustOpenTrans.canSettle()
        {
            // CustOpenTrans.doSettlement()
            manager.updateSpecTransWithSelectedDate();
            manager.settleMarkedTrans();

            info(strFmt("@MET:InvoiceSettled"));
        }
    }
}
